styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(14, 1fr);
  align-items: start;
  column-gap: var(--g-gap);
  padding-bottom: var(--h0);
}
section[data-skill-hub] .-w div {
  grid-column-start: 1;
  grid-column-end: 15;
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
  height: calc(var(--vh, 1vh) * 80);
}
section[data-skill-hub] .-w span {
  margin-top: calc(var(--vh, 1vh) * 10);
}
section[data-skill-hub] .-w figure {
  overflow: hidden;
  box-shadow: inset 0 0 0 1px var(--c-grey-dark);
}
section[data-skill-hub] .-w figure img {
  scale: 2;
  opacity: 0;
  clip-path: polygon(50% 50%, 50% 50%, 50% 50%, 50% 50%);
}
section[data-skill-hub] .-w figure.-inview {}
section[data-skill-hub] .-w figure.-inview img {
  scale: 1;
  opacity: 1;
  clip-path: polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%);
  transition:
    scale var(--easing-timing) var(--easing-function),
    opacity var(--easing-timing) var(--easing-function),
    clip-path var(--easing-timing) var(--easing-function)
  ;
}
section[data-skill-hub] .-w .image-1 {
  grid-row-start: 2;
  grid-column-start: 2;
  grid-column-end: 7;
}
section[data-skill-hub] .-w .image-2 {
  grid-row-start: 2;
  grid-column-start: 10;
  grid-column-end: 13;
}
section[data-skill-hub] .-w .image-3 {
  grid-row-start: 3;
  grid-row-end: 4;
  grid-column-start: 4;
  grid-column-end: 8;
}
section[data-skill-hub] .-w .image-4 {
  grid-row-start: 4;
  grid-row-end: 5;
  grid-column-start: 10;
  grid-column-end: 14;
}
section[data-skill-hub] .-w .image-5 {
  grid-row-start: 6;
  grid-column-start: 2;
  grid-column-end: 5;
}
section[data-skill-hub] .-w .image-6 {
  grid-row-start: 6;
  grid-column-start: 7;
  grid-column-end: 11;
  align-self: end;
}
